The number of completions from any state depends only on the current cell, the direction used to arrive there and how many turns have already been spent. With at most $30\times30\times3\times31$ states a memoised recursion with a cap of $10^{19}$ is easily fast enough. The total count for a prefix is obtained from the DP, so the k-th lexicographic route can be built greedily: try `R` first, skip it if `k` is larger than the number of completions behind it, otherwise fix it and continue with the same procedure for the next character.

```python
from functools import lru_cache
from typing import List, Tuple

def kth_route(width: int, height: int, blocked: List[Tuple[int, int]], max_turns: int, k: int) -> str | None:
    if k < 1:
        raise ValueError("k must be >= 1")
    blocked_set = set(blocked)
    if (0, 0) in blocked_set or (width - 1, height - 1) in blocked_set:
        return None
    if width == 1 and height == 1:
        return ""

    INF = 10 ** 19

    @lru_cache(maxsize=None)
    def count(x: int, y: int, prev: int, turns_used: int) -> int:
        # prev: -1 = start, 0 = R, 1 = U
        if (x, y) in blocked_set:
            return 0
        if x == width - 1 and y == height - 1:
            return 1
        if turns_used > max_turns:
            return 0
        # prune impossible remaining steps
        need_r = width - 1 - x
        need_u = height - 1 - y
        if need_r < 0 or need_u < 0:
            return 0

        total = 0
        # R
        if x < width - 1:
            nx, ny = x + 1, y
            if (nx, ny) not in blocked_set:
                nturn = turns_used + (0 if prev == -1 or prev == 0 else 1)
                if nturn <= max_turns:
                    total += count(nx, ny, 0, nturn)
                    if total >= INF:
                        return INF
        # U
        if y < height - 1:
            nx, ny = x, y + 1
            if (nx, ny) not in blocked_set:
                nturn = turns_used + (0 if prev == -1 or prev == 1 else 1)
                if nturn <= max_turns:
                    total += count(nx, ny, 1, nturn)
                    if total >= INF:
                        return INF
        return total if total < INF else INF

    total_paths = count(0, 0, -1, 0)
    if k > total_paths:
        return None

    x = y = 0
    prev = -1
    turns_used = 0
    res_chars = []

    while not (x == width - 1 and y == height - 1):
        # try R
        if x < width - 1 and (x + 1, y) not in blocked_set:
            nturn = turns_used + (0 if prev == -1 or prev == 0 else 1)
            if nturn <= max_turns:
                cnt = count(x + 1, y, 0, nturn)
                if k > cnt:
                    k -= cnt
                    # R not chosen
                else:
                    # choose R
                    res_chars.append('R')
                    x += 1
                    prev = 0
                    turns_used = nturn
                    continue
            else:
                cnt = 0
        # try U
        if y < height - 1 and (x, y + 1) not in blocked_set:
            nturn = turns_used + (0 if prev == -1 or prev == 1 else 1)
            if nturn <= max_turns:
                cnt = count(x, y + 1, 1, nturn)
                if k > cnt:
                    k -= cnt
                    # shouldn't happen because total_paths guarantees a solution
                else:
                    res_chars.append('U')
                    y += 1
                    prev = 1
                    turns_used = nturn
                    continue
            else:
                cnt = 0
        # no move possible
        return None

    return ''.join(res_chars)
