import re

def unpack_fields(layout: str, data: bytes) -> dict:
    # ---------- tokenize ----------
    token_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*|\d+|\[|\]|{|}|;')
    tokens = []
    pos = 0
    for m in token_re.finditer(layout):
        start, end = m.span()
        gap = layout[pos:start]
        if gap.strip() != '':
            raise ValueError('stray characters')
        val = m.group()
        if val in '[]{};':
            typ = 'SYMBOL'
        elif val.isdigit():
            typ = 'NUMBER'
        else:
            typ = 'WORD'
        tokens.append((typ, val, start, end))
        pos = end
    tail = layout[pos:]
    if tail.strip() != '':
        raise ValueError('stray characters')
    for i in range(1, len(tokens)):
        prev_typ, _, prev_end, _ = tokens[i-1]
        cur_typ, _, cur_start, _ = tokens[i]
        if prev_typ == 'WORD' and cur_typ == 'WORD':
            between = layout[tokens[i-1][3]:cur_start]
            if not any(c.isspace() for c in between):
                raise ValueError('adjacent words')
    # ---------- parser ----------
    class P:
        def __init__(self, toks):
            self.toks = toks
            self.i = 0
        def peek(self):
            return self.toks[self.i] if self.i < len(self.toks) else None
        def consume(self):
            t = self.toks[self.i]
            self.i += 1
            return t
        def expect(self, val):
            t = self.peek()
            if not t or t[1] != val:
                raise ValueError(f'expected {val}')
            self.i += 1
            return t
        def expect_word(self):
            t = self.peek()
            if not t or t[0] != 'WORD':
                raise ValueError('expected word')
            self.i += 1
            return t[1]
        def expect_number(self):
            t = self.peek()
            if not t or t[0] != 'NUMBER':
                raise ValueError('expected number')
            self.i += 1
            return int(t[1])

    def valid_name(s):
        return re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', s) is not None

    class FieldNode: pass
    class BytesNode: pass
    class TextNode: pass
    class PadNode: pass
    class GroupNode: pass

    def parse_type(tok):
        m = re.fullmatch(r'([ui])(8|16|24|32)(le)?', tok)
        if not m:
            raise ValueError('unknown type')
        base, sz, le = m.groups()
        signed = base == 'i'
        endian = 'little' if le else 'big'
        return int(sz), signed, endian

    def parse_stmt_list(end_tok=None):
        nodes = []
        while True:
            t = p.peek()
            if not t:
                if end_tok:
                    break
                break
            if t[1] == ';':
                p.consume()
                continue
            if end_tok and t[1] == end_tok:
                break
            node = parse_stmt()
            nodes.append(node)
            # after statement
            t2 = p.peek()
            if t2 and t2[1] == ';':
                p.consume()
                continue
            if end_tok and t2 and t2[1] == end_tok:
                continue
            if not t2:
                break
            raise ValueError('missing ;')
        return nodes

    def parse_stmt():
        t = p.peek()
        if not t:
            raise ValueError()
        if t[1] == 'pad':
            return parse_pad()
        if t[1] == 'group':
            return parse_group()
        if t[1] == 'bytes':
            return parse_bytes()
        if t[1] == 'text':
            return parse_text()
        # field
        return parse_field()

    def parse_field():
        typ = p.expect_word()
        sz, signed, endian = parse_type(typ)
        name = p.expect_word()
        if not valid_name(name):
            raise ValueError('bad name')
        count_expr = None
        if p.peek() and p.peek()[1] == '[':
            p.consume()
            ct = p.peek()
            if ct[0] == 'NUMBER':
                count_expr = p.expect_number()
            elif ct[0] == 'WORD':
                count_expr = p.expect_word()
            else:
                raise ValueError('bad count')
            p.expect(']')
        node = type('F', (), {})()
        node.__class__ = FieldNode
        node.type_sz = sz
        node.type_signed = signed
        node.type_endian = endian
        node.name = name
        node.count_expr = count_expr
        return node

    def parse_bytes():
        p.expect_word()  # 'bytes'
        name = p.expect_word()
        if not valid_name(name):
            raise ValueError()
        p.expect('[')
        ct = p.peek()
        if ct[0] == 'NUMBER':
            count = p.expect_number()
        elif ct[0] == 'WORD':
            count = p.expect_word()
        else:
            raise ValueError()
        p.expect(']')
        node = type('B', (), {})()
        node.__class__ = BytesNode
        node.name = name
        node.count_expr = count
        return node

    def parse_text():
        p.expect_word()
        name = p.expect_word()
        p.expect('[')
        ct = p.peek()
        if ct[0] == 'NUMBER':
            count = p.expect_number()
        elif ct[0] == 'WORD':
            count = p.expect_word()
        else:
            raise ValueError()
        p.expect(']')
        node = type('T', (), {})()
        node.__class__ = TextNode
        node.name = name
        node.count_expr = count
        return node

    def parse_pad():
        p.expect_word()
        p.expect('[')
        ct = p.peek()
        if ct[0] == 'NUMBER':
            count = p.expect_number()
        elif ct[0] == 'WORD':
            count = p.expect_word()
        else:
            raise ValueError()
        p.expect(']')
        node = type('P', (), {})()
        node.__class__ = PadNode
        node.count_expr = count
        return node

    def parse_group():
        p.expect_word()
        name = p.expect_word()
        if not valid_name(name):
            raise ValueError()
        p.expect('[')
        ct = p.peek()
        if ct[0] == 'NUMBER':
            count = p.expect_number()
        elif ct[0] == 'WORD':
            count = p.expect_word()
        else:
            raise ValueError()
        p.expect(']')
        p.expect('{')
        body = parse_stmt_list(end_tok='}')
        p.expect('}')
        node = type('G', (), {})()
        node.__class__ = GroupNode
        node.name = name
        node.count_expr = count
        node.body = body
        return node

    p = P(tokens)
    top_nodes = parse_stmt_list()
    if p.i != len(tokens):
        raise ValueError('stray tokens')

    # duplicate names check
    def check_dups(nodes):
        seen = set()
        for n in nodes:
            if isinstance(n, (FieldNode, BytesNode, TextNode, GroupNode)):
                if n.name in seen:
                    raise ValueError('duplicate name')
                seen.add(n.name)
            if isinstance(n, GroupNode):
                check_dups(n.body)
    check_dups(top_nodes)

    # ---------- decoding ----------
    def resolve_count(expr, cur, parents):
        if isinstance(expr, int):
            return expr
        if expr in cur:
            v = cur[expr]
        else:
            v = None
            for ctx in reversed(parents):
                if expr in ctx:
                    v = ctx[expr]
                    break
            if v is None:
                raise ValueError('count name not found')
        if not isinstance(v, int) or isinstance(v, bool):
            raise ValueError('count not int')
        if v < 0:
            raise ValueError('count negative')
        return v

    def read_int(off, sz, signed, endian):
        if off + sz > len(data):
            raise ValueError('out of data')
        raw = data[off:off+sz]
        v = int.from_bytes(raw, endian, signed=signed)
        return v, off + sz

    def decode_nodes(nodes, off, parents):
        cur = {}
        for n in nodes:
            if isinstance(n, FieldNode):
                cnt_expr = n.count_expr
                if cnt_expr is None:
                    reps = 1
                    is_list = False
                else:
                    reps = resolve_count(cnt_expr, cur, parents)
                    is_list = True
                vals = []
                for _ in range(reps):
                    v, off = read_int(off, n.type_sz, n.type_signed, n.type_endian)
                    vals.append(v)
                if is_list:
                    cur[n.name] = vals
                else:
                    cur[n.name] = vals[0]
            elif isinstance(n, BytesNode):
                cnt = resolve_count(n.count_expr, cur, parents)
                if off + cnt > len(data):
                    raise ValueError('out of data')
                cur[n.name] = bytes(data[off:off+cnt])
                off += cnt
            elif isinstance(n, TextNode):
                cnt = resolve_count(n.count_expr, cur, parents)
                if off + cnt > len(data):
                    raise ValueError('out of data')
                raw = data[off:off+cnt]
                if any(b >= 0x80 for b in raw):
                    raise ValueError('non ascii')
                s = raw.rstrip(b'\x00').decode('ascii')
                cur[n.name] = s
                off += cnt
            elif isinstance(n, PadNode):
                cnt = resolve_count(n.count_expr, cur, parents)
                if off + cnt > len(data):
                    raise ValueError('out of data')
                off += cnt
            elif isinstance(n, GroupNode):
                reps = resolve_count(n.count_expr, cur, parents)
                lst = []
                for _ in range(reps):
                    body_cur, off = decode_nodes(n.body, off, parents + [cur])
                    lst.append(body_cur)
                cur[n.name] = lst
            else:
                raise ValueError()
        return cur, off

    cur_dict, final_off = decode_nodes(top_nodes, 0, [])
    if final_off != len(data):
        raise ValueError('data left over')
    return cur_dict
