from collections import deque

class SwapDesk:
    def __init__(self):
        self._next_id = 1
        self._orders = {}          # id -> dict
        self._buy = {}             # price -> deque of ids
        self._sell = {}

    # helpers
    def _levels(self, side):
        return self._buy if side == "buy" else self._sell

    def _can_fill(self, side, price, qty, owner):
        if side == "buy":
            for p in sorted(self._sell):
                if p > price:
                    break
                for oid in self._sell[p]:
                    o = self._orders.get(oid)
                    if o and o.get("active") and o["owner"] != owner:
                        qty -= o["qty"]
                        if qty <= 0:
                            return True
        else:
            for p in sorted(self._buy, reverse=True):
                if p < price:
                    break
                for oid in self._buy[p]:
                    o = self._orders.get(oid)
                    if o and o.get("active") and o["owner"] != owner:
                        qty -= o["qty"]
                        if qty <= 0:
                            return True
        return False

    def _match(self, side, price, qty, owner):
        remaining = qty
        trades = []
        if side == "buy":
            levels = self._sell
            prices = [p for p in levels if p <= price]
            for p in sorted(prices):
                q = levels.get(p)
                if not q:
                    continue
                i = 0
                while i < len(q) and remaining > 0:
                    oid = q[i]
                    o = self._orders.get(oid)
                    if not o or not o.get("active"):
                        q.pop(i)
                        continue
                    if o["owner"] == owner:
                        q.pop(i)
                        o["active"] = False
                        continue
                    trade_qty = min(remaining, o["qty"])
                    trades.append((oid, o["price"], trade_qty))
                    remaining -= trade_qty
                    o["qty"] -= trade_qty
                    if o["qty"] == 0:
                        o["active"] = False
                        q.pop(i)
                    else:
                        i += 1
                if not q:
                    del levels[p]
                if remaining == 0:
                    break
        else:
            levels = self._buy
            prices = [p for p in levels if p >= price]
            for p in sorted(prices, reverse=True):
                q = levels.get(p)
                if not q:
                    continue
                i = 0
                while i < len(q) and remaining > 0:
                    oid = q[i]
                    o = self._orders.get(oid)
                    if not o or not o.get("active"):
                        q.pop(i)
                        continue
                    if o["owner"] == owner:
                        q.pop(i)
                        o["active"] = False
                        continue
                    trade_qty = min(remaining, o["qty"])
                    trades.append((oid, o["price"], trade_qty))
                    remaining -= trade_qty
                    o["qty"] -= trade_qty
                    if o["qty"] == 0:
                        o["active"] = False
                        q.pop(i)
                    else:
                        i += 1
                if not q:
                    del levels[p]
                if remaining == 0:
                    break
        return trades, remaining

    # public API
    def limit(self, owner: str, side: str, price: int, qty: int, tif: str = "gtc"):
        if side not in ("buy", "sell") or tif not in ("gtc", "ioc", "fok") or price < 1 or qty < 1:
            raise ValueError
        oid = self._next_id
        self._next_id += 1
        self._orders[oid] = {"owner": owner, "side": side, "price": price, "qty": qty, "active": False}

        if tif == "fok" and not self._can_fill(side, price, qty, owner):
            # nothing happens
            self._orders[oid]["active"] = False
            return oid, []

        trades, remaining = self._match(side, price, qty, owner)

        if remaining > 0 and tif == "gtc":
            o = self._orders[oid]
            o["qty"] = remaining
            o["active"] = True
            lvl = self._levels(side)
            dq = lvl.setdefault(price, deque())
            dq.append(oid)
        else:
            self._orders[oid]["active"] = False

        return oid, trades

    def cancel(self, order_id) -> bool:
        o = self._orders.get(order_id)
        if not o or not o.get("active"):
            return False
        side = o["side"]
        price = o["price"]
        lvl = self._levels(side)
        dq = lvl.get(price)
        if dq and order_id in dq:
            dq.remove(order_id)
            if not dq:
                del lvl[price]
        o["active"] = False
        return True

    def amend(self, order_id, qty) -> bool:
        if qty < 1:
            raise ValueError
        o = self._orders.get(order_id)
        if not o or not o.get("active"):
            return False
        old = o["qty"]
        o["qty"] = qty
        if qty > old:
            side = o["side"]
            price = o["price"]
            lvl = self._levels(side)
            dq = lvl.get(price)
            if dq and order_id in dq:
                dq.remove(order_id)
                dq.append(order_id)
        return True

    def best(self, side):
        if side == "buy":
            if not self._buy:
                return None
            price = max(self._buy)
            total = sum(self._orders[oid]["qty"] for oid in self._buy[price] if self._orders[oid].get("active"))
            return (price, total)
        else:
            if not self._sell:
                return None
            price = min(self._sell)
            total = sum(self._orders[oid]["qty"] for oid in self._sell[price] if self._orders[oid].get("active"))
            return (price, total)

    def depth(self, side, levels):
        if side == "buy":
            prices = sorted(self._buy.keys(), reverse=True)
        else:
            prices = sorted(self._sell.keys())
        res = []
        for p in prices[:levels]:
            lvl = self._buy if side == "buy" else self._sell
            dq = lvl.get(p, deque())
            total = sum(self._orders[oid]["qty"] for oid in dq if self._orders[oid].get("active"))
            res.append((p, total))
        return res

    def open_orders(self, owner):
        out = []
        for oid in sorted(self._orders):
            o = self._orders[oid]
            if o.get("active") and o["owner"] == owner:
                out.append((oid, o["side"], o["price"], o["qty"]))
        return out
