The sled state is defined by its position, velocity and which beacons have been collected. From a state the next velocity is limited by the ice rule and by the bounds `-3..3`. A move is legal only when every horizontal then vertical step stays inside the board and avoids walls. Beacons are collected along the traversed cells and the search proceeds with a breadth-first queue, guaranteeing the first time the goal with zero velocity and all beacons is reached is optimal. The total number of states is at most `144 * 7 * 7 * 4`, easily searchable.

```python
from collections import deque

def sled_ticks(grid):
    if not grid:
        return None
    R = len(grid)
    C = len(grid[0])
    start = goal = None
    beacons = []
    ice = set()
    for r in range(R):
        row = grid[r]
        for c in range(C):
            ch = row[c]
            if ch == 'S':
                start = (r, c)
            elif ch == 'G':
                goal = (r, c)
            elif ch == '~':
                ice.add((r, c))
            elif ch == '*':
                beacons.append((r, c))
    if start is None or goal is None:
        return None

    beacon_index = {pos:i for i, pos in enumerate(beacons)}
    all_mask = (1 << len(beacons)) - 1

    def in_bounds(r, c):
        return 0 <= r < R and 0 <= c < C

    def cell_free(r, c):
        return in_bounds(r, c) and grid[r][c] != '#'

    def move_ok(r, c, vx, vy):
        # horizontal
        nc = c
        if vx != 0:
            step = 1 if vx > 0 else -1
            for _ in range(abs(vx)):
                nc += step
                nr = r
                if not cell_free(nr, nc):
                    return False
        # vertical
        nr = r
        if vy != 0:
            step = 1 if vy > 0 else -1
            for _ in range(abs(vy)):
                nr += step
                if not cell_free(nr, nc):
                    return False
        return True

    def next_pos(r, c, vx, vy):
        nc = c + vx
        nr = r + vy
        return nr, nc

    def collect_mask(r, c, vx, vy, mask):
        # walk the path and set bits
        # horizontal
        nr, nc = r, c
        if vx != 0:
            step = 1 if vx > 0 else -1
            for _ in range(abs(vx)):
                nc += step
                if (nr, nc) in beacon_index:
                    mask |= 1 << beacon_index[(nr, nc)]
        # vertical
        if vy != 0:
            step = 1 if vy > 0 else -1
            for _ in range(abs(vy)):
                nr += step
                if (nr, nc) in beacon_index:
                    mask |= 1 << beacon_index[(nr, nc)]
        # final cell already covered by last iteration, but ensure
        if (nr, nc) in beacon_index:
            mask |= 1 << beacon_index[(nr, nc)]
        return mask

    sr, sc = start
    gr, gc = goal
    start_mask = 0
    if (sr, sc) in beacon_index:
        start_mask |= 1 << beacon_index[(sr, sc)]

    q = deque()
    q.append((sr, sc, 0, 0, start_mask, 0))
    visited = set()
    visited.add((sr, sc, 0, 0, start_mask))

    while q:
        r, c, vx, vy, mask, d = q.popleft()
        on_ice = (r, c) in ice
        vx_choices = [vx] if on_ice else range(max(-3, vx-1), min(3, vx+1)+1)
        vy_choices = [vy] if on_ice else range(max(-3, vy-1), min(3, vy+1)+1)
        for nvx in vx_choices:
            for nvy in vy_choices:
                if not move_ok(r, c, nvx, nvy):
                    continue
                nr, nc = next_pos(r, c, nvx, nvy)
                nmask = collect_mask(r, c, nvx, nvy, mask)
                # also collect starting cell if we never collected it (zero move)
                if (r, c) in beacon_index and (nvx == 0 and nvy == 0):
                    nmask |= 1 << beacon_index[(r, c)]
                nd = d + 1
                if nr == gr and nc == gc and nvx == 0 and nvy == 0 and nmask == all_mask:
                    return nd
                state = (nr, nc, nvx, nvy, nmask)
                if state not in visited:
                    visited.add(state)
                    q.append((nr, nc, nvx, nvy, nmask, nd))
    return None
