def understaffed(shifts, breaks, demand, horizon):
    from collections import defaultdict
    import bisect

    shifts_by = defaultdict(list)
    for w, s, e in shifts:
        if e > s:
            shifts_by[w].append((s, e))

    breaks_by = defaultdict(list)
    for w, s, e in breaks:
        if e > s:
            breaks_by[w].append((s, e))

    presence = []

    for w, segs in shifts_by.items():
        segs.sort()
        merged = []
        cur_s, cur_e = segs[0]
        for s, e in segs[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
            else:
                merged.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged.append((cur_s, cur_e))

        br = breaks_by.get(w)
        if not br:
            for s, e in merged:
                presence.append((s, e))
            continue

        br.sort()
        merged_br = []
        cur_s, cur_e = br[0]
        for s, e in br[1:]:
            if s <= cur_e:
                if e > cur_e:
                    cur_e = e
            else:
                merged_br.append((cur_s, cur_e))
                cur_s, cur_e = s, e
        merged_br.append((cur_s, cur_e))

        for s_shift, e_shift in merged:
            cur = s_shift
            for bs, be in merged_br:
                if be <= cur or bs >= e_shift:
                    continue
                if bs > cur:
                    presence.append((cur, min(bs, e_shift)))
                cur = max(cur, be)
                if cur >= e_shift:
                    break
            if cur < e_shift:
                presence.append((cur, e_shift))

    # demand with last-wins for same time
    time_to_req = {}
    for idx, (t, req) in enumerate(demand):
        if t not in time_to_req:
            time_to_req[t] = req
        # later in list wins, we just overwrite each time
        # but need to keep last occurrence per time, simple overwrite in order
        time_to_req[t] = req   # last wins because we iterate in order
    demand_sorted = sorted(time_to_req.items())  # list of (t, req)
    demand_times = [t for t, _ in demand_sorted]
    demand_reqs = [r for _, r in demand_sorted]
    demand_map = dict(demand_sorted)

    points_set = {0, horizon}
    for s, e in presence:
        if e <= 0 or s >= horizon:
            continue
        points_set.add(max(s, 0))
        points_set.add(min(e, horizon))
    for t, _ in demand_sorted:
        if 0 <= t < horizon:
            points_set.add(t)
    points = sorted(points_set)

    delta = {}
    for s, e in presence:
        ns = max(s, 0)
        ne = min(e, horizon)
        if ns >= ne:
            continue
        delta[ns] = delta.get(ns, 0) + 1
        delta[ne] = delta.get(ne, 0) - 1

    # initial required for t = 0
    idx0 = bisect.bisect_right(demand_times, 0) - 1
    cur_req = demand_reqs[idx0] if idx0 >= 0 else 0

    cur_present = 0
    seg_start = None
    seg_def = None
    res = []

    for i in range(len(points) - 1):
        t = points[i]
        cur_present += delta.get(t, 0)
        if t in demand_map:
            cur_req = demand_map[t]

        a = t
        b = points[i + 1]
        if b <= 0 or a >= horizon:
            continue
        a = max(a, 0)
        b = min(b, horizon)
        if a >= b:
            continue

        deficit = cur_req - cur_present
        if deficit > 0:
            if seg_def is None:
                seg_start = a
                seg_def = deficit
            elif deficit != seg_def:
                res.append((seg_start, a, seg_def))
                seg_start = a
                seg_def = deficit
            # else continue same segment
        else:
            if seg_def is not None:
                res.append((seg_start, a, seg_def))
                seg_def = None
                seg_start = None

    if seg_def is not None:
        res.append((seg_start, points[-1], seg_def))

    return res
```

The permutation produced by one execution of the program is built directly from the identity array, which allows each move to be applied with simple list operations. Validation of all moves is performed first using a strict regular expression for integers and explicit range checks. Once the single-round permutation is known, its power is obtained by decomposing it into disjoint cycles, which makes exponentiation for up to $10^{18}$ rounds linear in $n$. The final answers for the requested positions are then read from the powered permutation.

```python
import re
from math import ceil

_int_re = re.compile(r'-?\d+$')

def shuffle_rounds(n: int, program: list[str], rounds: int, positions: list[int]) -> list[int]:
    # ---------- validation ----------
    for s in program:
        parts = s.strip().split()
        if not parts:
            raise ValueError
        name = parts[0]
        if name == 'rot':
            if len(parts) != 2:
                raise ValueError
            if not _int_re.fullmatch(parts[1]):
                raise ValueError
            # int conversion is fine, value may be huge
        elif name == 'rev':
            if len(parts) != 3:
                raise ValueError
            if not (_int_re.fullmatch(parts[1]) and _int_re.fullmatch(parts[2])):
                raise ValueError
            i = int(parts[1]); j = int(parts[2])
            if not (0 <= i < n and 0 <= j < n):
                raise ValueError
            if i > j:
                raise ValueError
        elif name == 'lift':
            if len(parts) != 3:
                raise ValueError
            if not (_int_re.fullmatch(parts[1]) and _int_re.fullmatch(parts[2])):
                raise ValueError
            i = int(parts[1]); j = int(parts[2])
            if not (0 <= i < n and 0 <= j < n):
                raise ValueError
            if i > j:
                raise ValueError
        elif name == 'swap':
            if len(parts) != 3:
                raise ValueError
            if not (_int_re.fullmatch(parts[1]) and _int_re.fullmatch(parts[2])):
                raise ValueError
            i = int(parts[1]); j = int(parts[2])
            if not (0 <= i < n and 0 <= j < n):
                raise ValueError
        elif name == 'weave':
            if len(parts) != 1:
                raise ValueError
        else:
            raise ValueError

    if rounds == 0:
        return list(positions)

    # ---------- one round permutation ----------
    arr = list(range(n))
    for s in program:
        parts = s.strip().split()
        name = parts[0]
        if name == 'rot':
            k = int(parts[1]) % n
            if k:
                arr = arr[-k:] + arr[:-k]   # right rotation
        elif name == 'rev':
            i = int(parts[1]); j = int(parts[2])
            arr[i:j+1] = arr[i:j+1][::-1]
        elif name == 'lift':
            i = int(parts[1]); j = int(parts[2])
            seg = arr[i:j+1]
            arr = seg + arr[:i] + arr[j+1:]
        elif name == 'swap':
            i = int(parts[1]); j = int(parts[2])
            arr[i], arr[j] = arr[j], arr[i]
        else:  # weave
            k = (n + 1) // 2
            front = arr[:k]
            back = arr[k:]
            res = []
            # interleave
            lb = len(back)
            lf = len(front)
            for idx in range(lb):
                res.append(front[idx])
                res.append(back[idx])
            if lb < lf:
                res.extend(front[lb:])
            arr = res

    perm = arr  # perm[pos] = tile after one round

    # ---------- permutation power ----------
    visited = [False] * n
    perm_pow = [0] * n
    for i in range(n):
        if visited[i]:
            continue
        cycle = []
        j = i
        while not visited[j]:
            visited[j] = True
            cycle.append(j)
            j = perm[j]
        L = len(cycle)
        shift = rounds % L
        for idx, node in enumerate(cycle):
            target = cycle[(idx + shift) % L]
            perm_pow[node] = target
    # perm_pow[pos] = tile after `rounds` rounds
    return [perm_pow[p] for p in positions]
